'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var airy = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof airy, 'function', 'main export is a function' );
	t.end();
});

tape( 'attached to the main export is an `assign` method', function test( t ) {
	t.strictEqual( hasOwnProp( airy, 'assign' ), true, 'has property' );
	t.strictEqual( typeof airy.assign, 'function', 'has method' );
	t.end();
});

tape( 'attached to the main export are `ai`, `aip`, `bi`, and `bip` methods', function test( t ) {
	t.strictEqual( hasOwnProp( airy, 'ai' ), true, 'has property ai' );
	t.strictEqual( hasOwnProp( airy, 'aip' ), true, 'has property aip' );
	t.strictEqual( hasOwnProp( airy, 'bi' ), true, 'has property bi' );
	t.strictEqual( hasOwnProp( airy, 'bip' ), true, 'has property bip' );
	t.strictEqual( typeof airy.ai, 'function', 'has method ai' );
	t.strictEqual( typeof airy.aip, 'function', 'has method aip' );
	t.strictEqual( typeof airy.bi, 'function', 'has method bi' );
	t.strictEqual( typeof airy.bip, 'function', 'has method bip' );
	t.end();
});
